<?php
require_once __DIR__.'/../auth_check.php';AccessManager::requirePageAccess();
require_once __DIR__.'/../model/Database.php';require_once __DIR__.'/../controllers/RhMissionController.php';require_once __DIR__.'/../services/PasskeySignatureGuard.php';
$pdo=Database::getConnection();$manager=(new RhMissionController($pdo))->missions();$userId=(int)($_SESSION['user_id']??0);$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{PasskeySignatureGuard::requireVerified($userId);$manager->signAssignedRequest((int)($_POST['request_id']??0),(string)($_POST['signature_mode']??'profile'),(string)($_POST['signature_data']??''),['user_id'=>$userId,'user_name'=>trim((string)($_SESSION['user_name']??'Utilisateur'))]);$message='Signature PO enregistrée.';}catch(Throwable $e){$error=$e->getMessage();}
$rows=$manager->assignedSignatures($userId);$pageTitle='Mes signatures d’ordres de mission';$activeMenu='rh_mission_signatures';require_once __DIR__.'/../decaissement/includes/header.php';require_once __DIR__.'/../decaissement/includes/navbar.php';
?>
<main class="min-h-screen bg-slate-50 px-4 py-8"><div class="mx-auto max-w-6xl"><header class="rounded-[30px] bg-black p-7 text-white shadow-xl"><p class="text-xs font-black uppercase tracking-[.3em] text-[#ffcc20]">FINÉA · Signature PO</p><h1 class="mt-3 text-3xl font-black">Mes ordres de mission à signer</h1><p class="mt-2 text-sm text-slate-300">Cet espace affiche uniquement les ordres qui vous ont été transmis et leur état.</p></header><?php if($message||$error): ?><div class="mt-5 rounded-2xl border p-4 <?=$error?'border-rose-200 bg-rose-50 text-rose-800':'border-emerald-200 bg-emerald-50 text-emerald-800'?>"><?=htmlspecialchars($error?:$message)?></div><?php endif ?>
<div class="mt-6 grid gap-4"><?php if(!$rows): ?><div class="rounded-3xl border bg-white p-8 text-center text-slate-500">Aucun ordre de mission ne vous a été transmis.</div><?php endif; foreach($rows as $row): ?><article class="rounded-3xl border bg-white p-6 shadow-sm"><div class="flex flex-wrap items-start justify-between gap-4"><div><span class="rounded-full bg-amber-100 px-3 py-1 text-xs font-black text-amber-900"><?=htmlspecialchars(strtoupper((string)$row['role']))?> · PO</span><h2 class="mt-3 text-xl font-black"><?=htmlspecialchars((string)$row['mission_code'].' · '.$row['mission_title'])?></h2><p class="mt-1 text-sm text-slate-600"><?=htmlspecialchars((string)$row['personnel_name'].' · '.$row['destination'])?></p></div><div class="text-right text-sm"><b><?=htmlspecialchars((string)$row['mission_status'])?></b><br><span class="text-slate-500"><?=htmlspecialchars((string)$row['start_date'].' → '.$row['end_date'])?></span></div></div><?php if($row['request_status']==='pending'): ?><form method="post" class="mt-5 rounded-2xl bg-slate-50 p-4"><input type="hidden" name="request_id" value="<?=(int)$row['id']?>"><select name="signature_mode" class="rounded-xl border px-3 py-2"><option value="profile">Utiliser ma signature de profil</option><option value="drawn">Signer directement</option></select><canvas class="signature-canvas mt-3 h-32 w-full touch-none rounded-xl border-2 border-dashed bg-white"></canvas><input type="hidden" name="signature_data"><button class="mt-3 rounded-xl bg-black px-5 py-2 text-sm font-black text-[#ffcc20]">Signer en PO</button></form><?php else: ?><p class="mt-4 font-bold text-emerald-700"><i class="fas fa-check-circle mr-2"></i>Signé le <?=htmlspecialchars((string)$row['signed_at'])?></p><?php endif ?></article><?php endforeach ?></div></div></main>
<script>document.querySelectorAll('.signature-canvas').forEach(c=>{const x=c.getContext('2d'),i=c.parentElement.querySelector('[name="signature_data"]');c.width=800;c.height=180;x.lineWidth=4;x.lineCap='round';let d=false;const p=e=>{const r=c.getBoundingClientRect(),q=e.touches?.[0]||e;return{x:(q.clientX-r.left)*c.width/r.width,y:(q.clientY-r.top)*c.height/r.height}};c.onpointerdown=e=>{d=true;const q=p(e);x.beginPath();x.moveTo(q.x,q.y)};c.onpointermove=e=>{if(!d)return;const q=p(e);x.lineTo(q.x,q.y);x.stroke();i.value=c.toDataURL()};c.onpointerup=c.onpointerleave=()=>d=false})</script>
